head.script:
scwin.trigger1_onclick = function(e) { //debugger;
    /*
    	dataListAutoRefresh default 값은 false 이나
    	dataListAutoRefresh="true" 를 권장하여 config.xml 에
    	기본으로 dataListAutoRefresh="true" 설정이 되어 있으며

    	addItem, deleteItem 의 refresh 인자를 주지 않을 경우 dataListAutoRefresh 값을 우선한다

    	refreshFlag = true 인 경우 dataList 갱신
    	refreshFlag = false 인 경우 dataList 미갱신

    */
    var refreshFlag = radio1.getValue();
    //selectbox.addItem : function(value, label, idx, refresh) 
    //selectbox.deleteItem : function(idx, refresh)
    if (refreshFlag == "true") {
        selectbox1.addItem("444", "ddd", 4, true);
    } else if (refreshFlag == "false") {
        selectbox1.addItem("444", "ddd", 4, false);
    } else {
        selectbox1.addItem("444", "ddd", 4);
    }
    textarea2.setValue(WebSquare.xml.indent(dataList1.getAllXML()));
};

scwin.checkVal = function() {
	let ccc = WebSquare.wUnit.getDomById('textarea2').value.indexOf('ccc');
	let ddd = WebSquare.wUnit.getDomById('textarea2').value.indexOf('ddd');
	console.log('ccc : ' + ccc);
	console.log('ddd : ' + ddd);
    return ccc < ddd;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('radio1').querySelectorAll('input')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");	
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();


scwin.onpageload = function() {
    dataList1.setData(['aaa', '111', 'bbb', '222', 'ccc', '333']);
}
